package orders

// An Orders shop's settings.json, checked: the Go twin of templates/commerce/orders/src/settings.ts `validateSettings` and src/plans/settings.ts `readPlans`. Every problem is said in
// plain words, all at once, with the TypeScript's sentences in the TypeScript's order, so a builder reads the same refusal from either runtime (proved on
// testdata/settings-vectors.json, generated by go/scripts/gen_orders_settings.ts). The readers every template shares (the payment block, `approvers`, `assistant` and its character)
// are in settings_check.go; the helpers other files use (itemName, itemOf, allSlots, slotOf, cutoffOf, highestOrderInr, advanceFor, LOWEST_LINK_INR, the payment module's
// capabilities) are at the end of this file.
//
// Where Go and JavaScript differ, and what is copied:
//   - a missing key and a JSON null are both nil in a decoded map. The TypeScript tells them apart: `x ?? default` (timezone, owner.language, advance.mode) takes the default for
//     both, `x === undefined` (languages, address, the cut-off, delivery, reminder, daysAhead, percent, holdMinutes, approveOverInr, a slot's cutoff and maxOrders, plans, credits)
//     takes it only for a missing key and refuses a null. Each reader asks `has` (the key is in the object) for the second kind.
//   - an object's keys are listed in the order the file wrote them (JavaScript's Object.keys keeps insertion order; a Go map does not): keyOrder() reads the file's order once.
//   - text the file's author typed is put into a sentence as it is, between plain double quotes, as a template literal does (never Go's %q, which escapes); JSON.stringify of a value
//     is jsJSON (no HTML escaping, JavaScript's number text).
//   - `.trim()` is language.TrimJS; `toLowerCase()` of a name is strings.ToLower (the simple Unicode mapping: a name with a dotted capital I or a final sigma could compare
//     differently, which no menu has met); Number.isInteger is any finite whole double (1e21 is whole, and is said as "1e+21", accounting.JSNumberString).

import (
	"encoding/json"
	"fmt"
	"math"
	"regexp"
	"sort"
	"strconv"
	"strings"

	"github.com/GeometerLabs/agents/go/internal/accounting"
	"github.com/GeometerLabs/agents/go/internal/language"
	"github.com/GeometerLabs/agents/go/internal/orders/words"
	"github.com/GeometerLabs/agents/go/internal/payments"
	"github.com/GeometerLabs/agents/go/internal/payments/ownermarked"
	"github.com/GeometerLabs/agents/go/internal/payments/upi"
	"github.com/GeometerLabs/agents/go/internal/runtime"
	"github.com/GeometerLabs/agents/go/internal/zone"
)

// Pickup and Delivery are the two ways an order is had (a slot belongs to one of them).
const (
	Pickup   = "pickup"
	Delivery = "delivery"
)

// MenuItem is settings.ts MenuItem.
type MenuItem struct {
	ID         string
	Names      map[string][]string // per language, only the shop's languages; the first name is the one the agent says
	PriceInr   int64               // whole rupees for one; also the floor the agent never agrees below
	DailyStock int64               // the most of this item the shop makes for one day
}

// Cutoff is settings.ts Cutoff: an order closes this many days before the slot's day, at this time ("20:00").
type Cutoff struct {
	DaysBefore int64
	Time       string
}

// Slot is settings.ts Slot. Names is nil when the slot has none (`names` left out); an empty, non-nil map is `"names": {}` as written.
type Slot struct {
	ID, From, To string
	Names        map[string][]string
	Cutoff       *Cutoff // nil: the shop's
	MaxOrders    *int64  // nil: no limit of its own
}

// SlotOfMode is one entry of allSlots: a slot with the way it belongs to.
type SlotOfMode struct {
	Slot *Slot
	Mode string // Pickup or Delivery
}

// DeliverySettings is settings.ts `delivery`: its slots and the places it goes to.
type DeliverySettings struct {
	Slots []Slot
	Area  []string
}

// PlanType is plans/settings.ts PlanType.
type PlanType struct {
	ID       string
	Names    map[string][]string
	SlotID   string
	Weekdays []int // 0 is Sunday; sorted
	PriceInr int64
}

// PlansSettings is plans/settings.ts PlansSettings.
type PlansSettings struct {
	Types   []PlanType
	Cutoff  Cutoff
	Credits string // "carry" or "refund"
}

// Payment is the shop's payment block: "upi" (the owner marks money, with the shop's UPI ID and the payee) or a gateway ("razorpay").
type Payment struct {
	Module, UpiID, Payee string
}

// Settings is an Orders shop's settings.json, checked (settings.ts Settings).
type Settings struct {
	Name       string
	Address    string
	HasAddress bool
	Timezone   string
	Languages  []string
	Menu       []MenuItem
	Orders     struct{ MaxPerDay, MaxItemsPerOrder, DaysAhead int64 }
	Cutoff     Cutoff
	Pickup     []Slot
	Delivery   *DeliverySettings // nil: the shop does not deliver
	Advance    struct {
		Mode                 string // "full" or "part"
		Percent, HoldMinutes int64
	}
	Reminder     *struct{ HoursBefore int64 } // nil: no reminder
	Cancellation struct{ WindowHours int64 }
	Refund       struct{ LimitInr int64 }
	Payment      Payment
	Owner        struct {
		Whatsapp, Language string
		ApproveOverInr     int64
	}
	// Approvers and Assistant are the blocks as the TypeScript's readers hand them back, CHECKED (defaults filled, unknown keys refused), as JSON values; nil when left out.
	Approvers map[string]any
	Assistant map[string]any
	Plans     *PlansSettings // nil: no plans
}

// ---- the readers' small parts -------------------------------------------------------------------------------------------------------------------------------------------------

func isObj(v any) (map[string]any, bool) {
	m, ok := v.(map[string]any)
	return m, ok
}

// isWhole is Number.isInteger over a value read from JSON.
func isWhole(v any) (float64, bool) {
	n, ok := v.(float64)
	if !ok || math.IsInf(n, 0) || n != math.Trunc(n) {
		return 0, false
	}
	return n, true
}

func has(m map[string]any, k string) bool { _, ok := m[k]; return ok }

func contains[T comparable](l []T, s T) bool {
	for _, x := range l {
		if x == s {
			return true
		}
	}
	return false
}

// num is a number as JavaScript writes it in a template literal.
func num(n float64) string { return accounting.JSNumberString(n) }

// jsQuote is JSON.stringify of a string: only `"`, `\` and the control characters are escaped (lower-case hex), as JavaScript does; nothing is HTML-escaped.
func jsQuote(s string) string {
	var b strings.Builder
	b.WriteByte('"')
	for _, r := range s {
		switch r {
		case '"':
			b.WriteString(`\"`)
		case '\\':
			b.WriteString(`\\`)
		case '\b':
			b.WriteString(`\b`)
		case '\f':
			b.WriteString(`\f`)
		case '\n':
			b.WriteString(`\n`)
		case '\r':
			b.WriteString(`\r`)
		case '\t':
			b.WriteString(`\t`)
		default:
			if r < 0x20 {
				fmt.Fprintf(&b, `\u%04x`, r)
			} else {
				b.WriteRune(r)
			}
		}
	}
	b.WriteByte('"')
	return b.String()
}

// jsJSON is JSON.stringify of a value read from JSON. An object's keys are written sorted (the file's order is not kept for a nested value; a sentence names one only for a weekday
// or a language that is an object, which no real file has); undefined (a missing key) is "undefined" as a template literal writes it.
func jsJSON(v any) string {
	switch x := v.(type) {
	case nil:
		return "null"
	case string:
		return jsQuote(x)
	case float64:
		if math.IsInf(x, 0) || math.IsNaN(x) {
			return "null"
		}
		return num(x)
	case bool:
		return strconv.FormatBool(x)
	case []any:
		parts := make([]string, len(x))
		for i, e := range x {
			parts[i] = jsJSON(e)
		}
		return "[" + strings.Join(parts, ",") + "]"
	case map[string]any:
		keys := make([]string, 0, len(x))
		for k := range x {
			keys = append(keys, k)
		}
		sort.Strings(keys)
		parts := make([]string, len(keys))
		for i, k := range keys {
			parts[i] = jsQuote(k) + ":" + jsJSON(x[k])
		}
		return "{" + strings.Join(parts, ",") + "}"
	}
	b, _ := json.Marshal(v)
	return string(b)
}

// jsString is String(v) for a value read from JSON.
func jsString(v any) string {
	switch x := v.(type) {
	case nil:
		return "null"
	case string:
		return x
	case float64:
		return num(x)
	case bool:
		return strconv.FormatBool(x)
	case []any:
		parts := make([]string, len(x))
		for i, e := range x {
			if e != nil {
				parts[i] = jsString(e)
			}
		}
		return strings.Join(parts, ",")
	}
	return "[object Object]"
}

// upperFirst and lowerFirst are `label.charAt(0).toUpperCase() + label.slice(1)` and its lower-case twin (every label starts with an ASCII letter).
func upperFirst(s string) string {
	if s == "" {
		return s
	}
	return strings.ToUpper(s[:1]) + s[1:]
}

func lowerFirst(s string) string {
	if s == "" {
		return s
	}
	return strings.ToLower(s[:1]) + s[1:]
}

var languageNames = map[string]string{"en": "English", "hi": "Hindi", "ml": "Malayalam", "kn": "Kannada"}

// languageList is settings.ts languageList: `"hi" (Hindi), "en" (English), ...` in LANGUAGES' order.
func languageList() string {
	parts := make([]string, len(runtime.LANGUAGES))
	for i, l := range runtime.LANGUAGES {
		parts[i] = `"` + l + `" (` + languageNames[l] + `)`
	}
	return strings.Join(parts, ", ")
}

var (
	idRe    = regexp.MustCompile(`^[a-z0-9-]+$`)
	phoneRe = regexp.MustCompile(`^\+\d{10,15}$`)
	clockRe = regexp.MustCompile(`^(\d{1,2}):(\d{2})$`)
)

// ParseClock is core/time.ts parseClock: "12:30" as minutes since midnight, or -1.
func ParseClock(text string) int {
	m := clockRe.FindStringSubmatch(text)
	if m == nil {
		return -1
	}
	h, _ := strconv.Atoi(m[1])
	mi, _ := strconv.Atoi(m[2])
	if h > 23 || mi > 59 {
		return -1
	}
	return h*60 + mi
}

// reader carries the problems and the order of each object's keys as the file wrote them (by JSON path: "", "/menu/0", "/menu/0/names").
type reader struct {
	errs  []string
	order map[string][]string
}

func (r *reader) add(s string) { r.errs = append(r.errs, s) }

func (r *reader) addf(format string, a ...any) { r.errs = append(r.errs, fmt.Sprintf(format, a...)) }

// keys is Object.keys of the object at a path: the file's order, else (a value not read from a file) sorted.
func (r *reader) keys(obj map[string]any, path string) []string {
	if o, ok := r.order[path]; ok && len(o) == len(obj) {
		return o
	}
	keys := make([]string, 0, len(obj))
	for k := range obj {
		keys = append(keys, k)
	}
	sort.Strings(keys)
	return keys
}

// unknownKeys is settings.ts unknownKeys.
func (r *reader) unknownKeys(obj map[string]any, path string, allowed []string, where string) {
	for _, k := range r.keys(obj, path) {
		if !contains(allowed, k) {
			r.add(`I don't know what "` + k + `" means in ` + where + `. Allowed: ` + strings.Join(allowed, ", ") + `.`)
		}
	}
}

// whole is settings.ts readWhole: a whole number between min and max, or a sentence (with `why` in brackets after it when given).
func (r *reader) whole(v any, label string, minV, maxV int64, why string) (int64, bool) {
	n, ok := isWhole(v)
	if !ok {
		r.add("Set " + label + " as a whole number, for example " + strconv.FormatInt(max(minV, 1), 10) + ".")
		return 0, false
	}
	if n < float64(minV) || n > float64(maxV) {
		tail := ""
		if why != "" {
			tail = " (" + why + ")"
		}
		r.add(upperFirst(label) + " must be between " + strconv.FormatInt(minV, 10) + " and " + strconv.FormatInt(maxV, 10) + ", not " + num(n) + tail + ".")
		return 0, false
	}
	return int64(n), true
}

// keyOrder decodes settings.json keeping each object's key order, by JSON path.
func keyOrder(raw []byte) map[string][]string {
	out := map[string][]string{}
	dec := json.NewDecoder(strings.NewReader(string(raw)))
	var walk func(path string) error
	walk = func(path string) error {
		t, err := dec.Token()
		if err != nil {
			return err
		}
		switch t {
		case json.Delim('{'):
			keys := []string{}
			for dec.More() {
				kt, err := dec.Token()
				if err != nil {
					return err
				}
				k := kt.(string)
				// a key written twice is one key, in the place it was first written (JSON.parse keeps the first place and the last value)
				if !contains(keys, k) {
					keys = append(keys, k)
				}
				if err := walk(path + "/" + k); err != nil {
					return err
				}
			}
			out[path] = keys
			_, err = dec.Token()
			return err
		case json.Delim('['):
			i := 0
			for dec.More() {
				if err := walk(path + "/" + strconv.Itoa(i)); err != nil {
					return err
				}
				i++
			}
			_, err = dec.Token()
			return err
		}
		return nil
	}
	_ = walk("")
	return out
}

// ---- validateSettings -----------------------------------------------------------------------------------------------------------------------------------------------------

var topKeys = []string{"name", "address", "timezone", "languages", "menu", "orders", "cutoff", "pickup", "delivery", "advance", "reminder", "cancellation", "refund", "payment", "owner", "approvers", "assistant", "plans"}

// ReadSettings is validateSettings over settings.json as decoded; raw is the file's bytes (for the keys' order), nil when not known. The settings, or every problem.
func ReadSettings(in map[string]any, raw []byte) (*Settings, []string) {
	r := &reader{order: map[string][]string{}}
	if raw != nil {
		r.order = keyOrder(raw)
	}
	s := &Settings{}
	r.unknownKeys(in, "", topKeys, "the settings")

	name, nameOK := in["name"].(string)
	if !nameOK || language.TrimJS(name) == "" {
		r.add(`Add the shop's name ("name").`)
	}
	s.Name = language.TrimJS(name)
	if has(in, "address") {
		if a, ok := in["address"].(string); ok {
			s.Address, s.HasAddress = a, true
		} else {
			r.add(`The address ("address") must be text.`)
		}
	}
	var tzv any = "Asia/Kolkata" // `input.timezone ?? "Asia/Kolkata"`: a null takes the default too
	if in["timezone"] != nil {
		tzv = in["timezone"]
	}
	tz, _ := tzv.(string)
	if tz == "" || tz == "Local" || !zone.Valid(tz) { // Go reads "" and "Local" as zones; Intl knows neither
		r.add("The time zone " + jsJSON(tzv) + ` is not one I know. Use a name like "Asia/Kolkata".`)
	} else {
		s.Timezone = tz
	}

	s.Languages = r.languages(in)
	s.Menu = r.menu(in["menu"], s.Languages)
	ordersOK := r.orders(in["orders"], s)
	cutoff, cutoffOK := r.cutoff(in, "cutoff", "/cutoff", `the cut-off ("cutoff")`, &Cutoff{DaysBefore: 1, Time: "20:00"})
	if cutoffOK {
		s.Cutoff = cutoff
	}
	used := map[string]bool{}
	s.Pickup = r.slots(in["pickup"], "/pickup", Pickup, used)
	if has(in, "delivery") {
		pickupIDs := map[string]bool{}
		for _, sl := range s.Pickup {
			pickupIDs[sl.ID] = true
		}
		s.Delivery = r.delivery(in["delivery"], pickupIDs)
	}
	r.advance(in, s)
	r.reminder(in, s)
	refundOK := r.cancellationAndRefund(in, s)
	r.payment(in, s)
	ownerOK := r.owner(in["owner"], s)
	owner := ""
	if ownerOK {
		owner = s.Owner.Whatsapp
	}
	r.approvers(in["approvers"], has(in, "approvers"), owner, refundOK, s.Refund.LimitInr, s)

	if len(r.errs) == 0 && ordersOK && len(s.Menu) > 0 {
		if high := s.highestOrderOnly(); high*100 > checkWords.RefundPaisePerDay {
			r.add("One order can come to " + language.FormatInrWhole(high) + " (the most items in an order, all of your dearest item), which is more than the " +
				language.FormatInrWhole(checkWords.RefundPaisePerDay/100) + ` that can be refunded in a day. Lower "orders.maxItemsPerOrder" or the price.`)
		}
	}
	r.assistant(in["assistant"], has(in, "assistant"), s)
	s.Plans = r.plans(in, s, cutoff, cutoffOK)
	if len(r.errs) > 0 {
		return nil, r.errs
	}
	return s, nil
}

func (r *reader) languages(in map[string]any) []string {
	def := []string{"hi", "en"}
	if !has(in, "languages") {
		return def
	}
	list, ok := in["languages"].([]any)
	if !ok || len(list) == 0 {
		r.add(`List at least one customer language ("languages"), for example ["hi", "en"].`)
		return def
	}
	var out []string
	for _, l := range list {
		ls, isS := l.(string)
		switch {
		case !isS || !contains(runtime.LANGUAGES, ls):
			r.add("The language " + jsJSON(l) + " is not supported yet. Use one of " + languageList() + ".")
		case contains(out, ls):
			r.add(`The language "` + ls + `" is listed twice.`)
		default:
			out = append(out, ls)
		}
	}
	if len(out) == 0 {
		return def
	}
	return out
}

// nameList is a list of names that are all non-blank text, trimmed; ok false when it is not one (or empty and `nonEmpty`).
func nameList(v any, nonEmpty bool) ([]string, bool) {
	list, ok := v.([]any)
	if !ok || (nonEmpty && len(list) == 0) {
		return nil, false
	}
	out := make([]string, 0, len(list))
	for _, n := range list {
		ns, isS := n.(string)
		if !isS || language.TrimJS(ns) == "" {
			return nil, false
		}
		out = append(out, language.TrimJS(ns))
	}
	return out, true
}

func (r *reader) menu(v any, langs []string) []MenuItem {
	list, ok := v.([]any)
	if !ok || len(list) == 0 {
		r.add(`Add at least one menu item ("menu") with a name, a price in rupees and a daily stock.`)
		return nil
	}
	var items []MenuItem
	seenIDs := map[string]bool{}
	seenNames := map[string]string{}
	for i, raw := range list {
		m, isMap := isObj(raw)
		label := fmt.Sprintf("Item number %d", i+1)
		if id, ok := m["id"].(string); isMap && ok {
			label = `Item "` + id + `"`
		}
		if !isMap {
			r.add(label + " must be an object with id, names, priceInr and dailyStock.")
			continue
		}
		path := "/menu/" + strconv.Itoa(i)
		r.unknownKeys(m, path, []string{"id", "names", "priceInr", "dailyStock"}, label)
		id, idOK := m["id"].(string)
		switch {
		case !idOK || !idRe.MatchString(id):
			r.add(label + ` needs an id made of lowercase letters, digits and dashes, for example "veg-thali".`)
		case seenIDs[id]:
			r.add(`Two items share the id "` + id + `". Each id must be different.`)
		default:
			seenIDs[id] = true
		}
		idText := jsString(m["id"])
		if !has(m, "id") {
			idText = "undefined"
		}
		names := map[string][]string{}
		if nm, ok := isObj(m["names"]); !ok {
			r.add(label + ` needs "names": what customers call it, per language, for example {"en": ["veg thali"], "hi": ["वेज थाली"]}.`)
		} else {
			r.unknownKeys(nm, path+"/names", runtime.LANGUAGES, label+"'s names")
			for _, lang := range langs {
				l, good := nameList(nm[lang], true)
				if !good {
					r.add(label + " needs at least one name in " + languageNames[lang] + ` ("` + lang + `"), because customers can write in it.`)
					continue
				}
				names[lang] = l
				for _, n := range l {
					key := strings.ToLower(n)
					if other, seen := seenNames[key]; seen && other != idText {
						r.add(`The name "` + n + `" is used by both "` + other + `" and "` + idText + `", so the agent could not tell which one a customer means.`)
					} else {
						seenNames[key] = idText
					}
				}
			}
		}
		price, priceOK := isWhole(m["priceInr"])
		priceOK = priceOK && price >= 1 && price <= 100_000
		if !priceOK {
			r.add(label + ` needs a price in whole rupees ("priceInr"), for example 120. It is also the lowest price the agent will ever agree to.`)
		}
		stock, stockOK := isWhole(m["dailyStock"])
		stockOK = stockOK && stock >= 1 && stock <= 10_000
		if !stockOK {
			r.add(label + ` needs the most you make in a day ("dailyStock"), a whole number from 1, for example 40.`)
		}
		if idOK && priceOK && stockOK {
			items = append(items, MenuItem{ID: id, Names: names, PriceInr: int64(price), DailyStock: int64(stock)})
		}
	}
	return items
}

func (r *reader) orders(v any, s *Settings) bool {
	m, ok := isObj(v)
	if !ok {
		r.add(`Add the order limits ("orders"): {"maxPerDay": 30, "maxItemsPerOrder": 10, "daysAhead": 7}.`)
		return false
	}
	r.unknownKeys(m, "/orders", []string{"maxPerDay", "maxItemsPerOrder", "daysAhead"}, "the order limits")
	perDay, a := r.whole(m["maxPerDay"], `the most orders in a day ("orders.maxPerDay")`, 1, 10_000, "")
	items, b := r.whole(m["maxItemsPerOrder"], `the most items in one order ("orders.maxItemsPerOrder")`, 1, 100, "a payment link is bound to this many of your dearest item")
	ahead, c := int64(7), true
	if has(m, "daysAhead") {
		ahead, c = r.whole(m["daysAhead"], `how many days ahead an order may be ("orders.daysAhead")`, 0, 60, "")
	}
	if !a || !b || !c {
		return false
	}
	s.Orders.MaxPerDay, s.Orders.MaxItemsPerOrder, s.Orders.DaysAhead = perDay, items, ahead
	return true
}

// cutoff is settings.ts readCutoff over obj[key]: a missing key takes the fallback when there is one (a null is refused).
func (r *reader) cutoff(obj map[string]any, key, path, label string, fallback *Cutoff) (Cutoff, bool) {
	if !has(obj, key) && fallback != nil {
		return *fallback, true
	}
	m, ok := isObj(obj[key])
	if !ok {
		r.add("Add " + label + `: {"daysBefore": 1, "time": "20:00"} closes orders at 8 pm the evening before.`)
		return Cutoff{}, false
	}
	r.unknownKeys(m, path, []string{"daysBefore", "time"}, label)
	days, daysOK := int64(0), true
	if has(m, "daysBefore") {
		days, daysOK = r.whole(m["daysBefore"], "the days before ("+label+")", 0, 7, "")
	}
	t, isS := m["time"].(string)
	if !isS || ParseClock(t) < 0 {
		r.add("The cut-off time in " + label + ` must be a 24-hour time like "20:00".`)
		return Cutoff{}, false
	}
	if !daysOK {
		return Cutoff{}, false
	}
	return Cutoff{DaysBefore: days, Time: t}, true
}

// slots is settings.ts readSlots (always with `required`). `used` holds the ids taken so far.
func (r *reader) slots(v any, path, where string, used map[string]bool) []Slot {
	m, ok := isObj(v)
	if !ok {
		r.add("Add the " + where + ` slots ("` + where + `"): {"slots": [{"id": "lunch", "from": "12:00", "to": "13:00"}]}.`)
		return nil
	}
	allowed := []string{"slots"}
	if where == Delivery {
		allowed = []string{"slots", "area"}
	}
	r.unknownKeys(m, path, allowed, "the "+where+" slots")
	list, isList := m["slots"].([]any)
	if !isList || len(list) == 0 {
		r.add("List at least one " + where + ` slot ("` + where + `.slots").`)
		return nil
	}
	var out []Slot
	for i, raw := range list {
		sm, isMap := isObj(raw)
		label := fmt.Sprintf("%s slot number %d", where, i+1)
		if id, ok := sm["id"].(string); isMap && ok {
			label = "The " + where + ` slot "` + id + `"`
		}
		if !isMap {
			r.add(label + " must be an object with id, from and to.")
			continue
		}
		at := path + "/slots/" + strconv.Itoa(i)
		r.unknownKeys(sm, at, []string{"id", "from", "to", "names", "cutoff", "maxOrders"}, label)
		id, idOK := sm["id"].(string)
		switch {
		case !idOK || !idRe.MatchString(id):
			r.add(label + ` needs an id made of lowercase letters, digits and dashes, for example "lunch".`)
		case used[id]:
			r.add(`Two slots share the id "` + id + `". Each slot (pickup or delivery) needs its own id.`)
		default:
			used[id] = true
		}
		from, to := -1, -1
		fromS, fOK := sm["from"].(string)
		toS, tOK := sm["to"].(string)
		if fOK {
			from = ParseClock(fromS)
		}
		if tOK {
			to = ParseClock(toS)
		}
		if from < 0 || to < 0 {
			r.add(label + ` needs "from" and "to" as 24-hour times like "12:00".`)
		} else if to <= from {
			r.add(label + " must end after it starts.")
		}
		var cut *Cutoff
		cutOK := true
		if has(sm, "cutoff") {
			c, ok := r.cutoff(sm, "cutoff", at+"/cutoff", label+"'s cut-off", nil)
			if ok {
				cut = &c
			}
			cutOK = ok
		}
		names, hasNames := r.slotNames(sm, at+"/names", label)
		var most *int64
		mostOK := true
		if has(sm, "maxOrders") {
			n, ok := r.whole(sm["maxOrders"], "the most orders for "+lowerFirst(label)+` ("maxOrders")`, 1, 10_000, "")
			if ok {
				most = &n
			}
			mostOK = ok
		}
		if idOK && from >= 0 && to >= 0 && to > from && cutOK && mostOK {
			sl := Slot{ID: id, From: fromS, To: toS, Cutoff: cut, MaxOrders: most}
			if hasNames {
				sl.Names = names
			}
			out = append(out, sl)
		}
	}
	return out
}

// slotNames is settings.ts readSlotNames: nil and false when left out (or not an object: the sentence is said).
func (r *reader) slotNames(sm map[string]any, path, label string) (map[string][]string, bool) {
	if !has(sm, "names") {
		return nil, false
	}
	m, ok := isObj(sm["names"])
	if !ok {
		r.add(label + `'s names ("names") must look like {"en": ["lunch"], "hi": ["लंच"]}.`)
		return nil, false
	}
	r.unknownKeys(m, path, runtime.LANGUAGES, label+"'s names")
	names := map[string][]string{}
	for _, lang := range runtime.LANGUAGES {
		if !has(m, lang) {
			continue
		}
		l, good := nameList(m[lang], false)
		if !good {
			r.add(label + "'s names in " + languageNames[lang] + ` ("` + lang + `") must be a list of words.`)
			continue
		}
		names[lang] = l
	}
	return names, true
}

func (r *reader) delivery(v any, used map[string]bool) *DeliverySettings {
	slots := r.slots(v, "/delivery", Delivery, used)
	m, _ := isObj(v)
	area, isList := m["area"].([]any)
	var places []string
	good := isList && len(area) > 0
	for _, a := range area {
		if as, ok := a.(string); !ok || language.TrimJS(as) == "" {
			good = false
		}
	}
	if !good {
		r.add(`List the places you deliver to ("delivery.area"), for example ["Kakkanad", "Edappally"]. An address that names none of them is not delivered to.`)
	} else {
		for _, a := range area {
			p := language.TrimJS(a.(string))
			twice := false
			for _, x := range places {
				if strings.ToLower(x) == strings.ToLower(p) {
					twice = true
				}
			}
			if twice {
				r.add(`The place "` + p + `" is listed twice.`)
			} else {
				places = append(places, p)
			}
		}
	}
	if len(slots) > 0 && len(places) > 0 {
		return &DeliverySettings{Slots: slots, Area: places}
	}
	return nil
}

func (r *reader) advance(in map[string]any, s *Settings) {
	s.Advance.Mode, s.Advance.Percent, s.Advance.HoldMinutes = "part", 50, 30
	if !has(in, "advance") {
		return
	}
	m, ok := isObj(in["advance"])
	if !ok {
		r.add(`The advance ("advance") must look like {"mode": "part", "percent": 50, "holdMinutes": 30}, or {"mode": "full"}.`)
		return
	}
	r.unknownKeys(m, "/advance", []string{"mode", "percent", "holdMinutes"}, "the advance")
	var mode any = "part" // `v.mode ?? "part"`
	if m["mode"] != nil {
		mode = m["mode"]
	}
	if mode != "full" && mode != "part" {
		r.add(`The advance mode ("advance.mode") must be "full" (all of the order) or "part" (a percentage of it).`)
		return
	}
	percent, pOK := int64(100), true
	if mode == "part" {
		percent = 50
		if has(m, "percent") {
			percent, pOK = r.whole(m["percent"], `the advance percentage ("advance.percent")`, 1, 99, `use mode "full" for all of it`)
		}
	}
	hold, hOK := int64(30), true
	if has(m, "holdMinutes") {
		hold, hOK = r.whole(m["holdMinutes"], `how long an order is held for the advance ("advance.holdMinutes")`, 5, 24*60, "")
	}
	if pOK && hOK {
		s.Advance.Mode, s.Advance.Percent, s.Advance.HoldMinutes = mode.(string), percent, hold
	}
}

func (r *reader) reminder(in map[string]any, s *Settings) {
	if !has(in, "reminder") {
		return
	}
	m, ok := isObj(in["reminder"])
	if !ok {
		r.add(`The reminder ("reminder") must look like {"hoursBefore": 2}.`)
		return
	}
	r.unknownKeys(m, "/reminder", []string{"hoursBefore"}, "the reminder")
	if h, ok := r.whole(m["hoursBefore"], `how many hours before the slot to remind the customer ("reminder.hoursBefore")`, 1, 168, ""); ok {
		s.Reminder = &struct{ HoursBefore int64 }{h}
	}
}

// cancellationAndRefund is readCancellation then readRefund; it says whether the refund limit was read (the approvers' two-above check needs it).
func (r *reader) cancellationAndRefund(in map[string]any, s *Settings) bool {
	if m, ok := isObj(in["cancellation"]); !ok {
		r.add(`Add the cancellation rule ("cancellation"): {"windowHours": 12}.`)
	} else {
		r.unknownKeys(m, "/cancellation", []string{"windowHours"}, "the cancellation rule")
		if w, ok := r.whole(m["windowHours"], `the cancellation window in hours ("cancellation.windowHours")`, 0, 14*24, ""); ok {
			s.Cancellation.WindowHours = w
		}
	}
	m, ok := isObj(in["refund"])
	if !ok {
		r.add(`Add the refund limit ("refund"): {"limitInr": 500}.`)
		return false
	}
	r.unknownKeys(m, "/refund", []string{"limitInr"}, "the refund limit")
	l, lOK := r.whole(m["limitInr"], `the refund limit ("refund.limitInr")`, 0, 1_000_000, "")
	if lOK {
		s.Refund.LimitInr = l
	}
	return lOK
}

func (r *reader) owner(v any, s *Settings) bool {
	m, ok := isObj(v)
	if !ok {
		r.add(`Add the owner ("owner") with their WhatsApp number, for example {"whatsapp": "+919800000000"}.`)
		return false
	}
	r.unknownKeys(m, "/owner", []string{"whatsapp", "language", "approveOverInr"}, "the owner")
	w, wOK := m["whatsapp"].(string)
	wOK = wOK && phoneRe.MatchString(w)
	if !wOK {
		r.add(`The owner's WhatsApp number ("owner.whatsapp") must start with + and the country code, then digits only, for example +919800000000.`)
	}
	var lv any = "en" // `v.language ?? "en"`
	if m["language"] != nil {
		lv = m["language"]
	}
	lang, isS := lv.(string)
	langOK := isS && contains(runtime.LANGUAGES, lang)
	if !langOK {
		r.add(`The owner's language ("owner.language") must be one of ` + languageList() + ".")
	}
	over, overOK := int64(0), true
	if has(m, "approveOverInr") {
		over, overOK = r.whole(m["approveOverInr"], `the order total above which you want to approve ("owner.approveOverInr"; 0 is never)`, 0, 10_000_000, "")
	}
	if !wOK || !langOK || !overOK {
		return false
	}
	s.Owner.Whatsapp, s.Owner.Language, s.Owner.ApproveOverInr = w, lang, over
	return true
}

// ---- the plans (plans/settings.ts readPlans) ------------------------------------------------------------------------------------------------------------------------------

var weekdayNames = map[string]int{"sun": 0, "mon": 1, "tue": 2, "wed": 3, "thu": 4, "fri": 5, "sat": 6}

// plans is readPlans. shopCutoff is the shop's cut-off when it was read (cutOK); a broken one is no fallback, so a plans block with no cut-off of its own is then refused too.
func (r *reader) plans(in map[string]any, s *Settings, shopCutoff Cutoff, cutOK bool) *PlansSettings {
	if !has(in, "plans") {
		return nil
	}
	v, ok := isObj(in["plans"])
	if !ok {
		r.add(`The plans ("plans") must be an object: {"types": [...], "credits": "carry"}.`)
		return nil
	}
	for _, k := range r.keys(v, "/plans") {
		if !contains([]string{"types", "cutoff", "credits"}, k) {
			r.add(`I don't know what "` + k + `" means in the plans. Allowed: types, cutoff, credits.`)
		}
	}
	var credits any = "carry"
	if has(v, "credits") {
		credits = v["credits"]
	}
	creditsOK := credits == "carry" || credits == "refund"
	if !creditsOK {
		r.add(`Say what happens to meal days the customer does not take ("plans.credits"): "carry" takes them off next month's payment, "refund" gives the money back at month end.`)
	}
	var fallback *Cutoff
	if cutOK {
		fallback = &shopCutoff
	}
	cutoff, planCutOK := r.cutoff(v, "cutoff", "/plans/cutoff", `the plans' pause and skip cut-off ("plans.cutoff")`, fallback)
	// the slots a plan may name: pickup then delivery, as `new Map([...pickup, ...delivery])` holds them
	slotIDs := []string{}
	for _, sl := range s.Pickup {
		slotIDs = append(slotIDs, sl.ID)
	}
	if s.Delivery != nil {
		for _, sl := range s.Delivery.Slots {
			slotIDs = append(slotIDs, sl.ID)
		}
	}
	var types []PlanType
	list, isList := v["types"].([]any)
	if !isList || len(list) == 0 {
		r.add(`List at least one plan ("plans.types"), for example {"id": "lunch-weekdays", "names": {"en": ["lunch plan"]}, "slotId": "lunch", "weekdays": [1,2,3,4,5], "priceInr": 2400}.`)
	}
	dailyRefundInr := float64(checkWords.RefundPaisePerDay) / 100
	for i, raw := range list {
		m, isMap := isObj(raw)
		label := fmt.Sprintf("Plan number %d", i+1)
		if id, ok := m["id"].(string); isMap && ok {
			label = `Plan "` + id + `"`
		}
		if !isMap {
			r.add(label + " must be an object with id, names, slotId, weekdays and priceInr.")
			continue
		}
		at := "/plans/types/" + strconv.Itoa(i)
		for _, k := range r.keys(m, at) {
			if !contains([]string{"id", "names", "slotId", "weekdays", "priceInr"}, k) {
				r.add(`I don't know what "` + k + `" means in ` + label + `. Allowed: id, names, slotId, weekdays, priceInr.`)
			}
		}
		id, idOK := m["id"].(string)
		if !idOK || !idRe.MatchString(id) {
			r.add(label + ` needs an id made of lowercase letters, digits and dashes, for example "lunch-weekdays".`)
		} else {
			for _, t := range types {
				if t.ID == id {
					r.add(`Two plans share the id "` + id + `". Each id must be different.`)
					break
				}
			}
		}
		names := map[string][]string{}
		nm, namesOK := isObj(m["names"])
		if !namesOK {
			r.add(label + ` needs "names": what customers call it, per language, for example {"en": ["lunch plan"]}.`)
		} else {
			for _, lang := range s.Languages {
				l, good := nameList(nm[lang], true)
				if !good {
					r.add(label + ` needs at least one name in "` + lang + `", because customers can write in it.`)
				} else {
					names[lang] = l
				}
			}
			for _, k := range r.keys(nm, at+"/names") {
				if !contains(runtime.LANGUAGES, k) {
					r.add(label + ` names a language "` + k + `" that is not supported.`)
				}
			}
		}
		slotID, slotIsS := m["slotId"].(string)
		slotOK := slotIsS && contains(slotIDs, slotID)
		if !slotOK {
			r.add(label + ` needs the id of one of your pickup or delivery slots ("slotId"). Yours: ` + strings.Join(slotIDs, ", ") + ".")
		}
		var days []int
		wl, wIsList := m["weekdays"].([]any)
		if !wIsList || len(wl) == 0 {
			r.add(label + ` needs the days a meal is sent ("weekdays"), for example [1, 2, 3, 4, 5] (0 is Sunday) or ["mon", "tue"].`)
		} else {
			for _, d := range wl {
				var n any = d
				if ds, isS := d.(string); isS {
					// WEEKDAY_NAMES[d.toLowerCase().slice(0, 3)]: the first three UTF-16 units of the lower-cased text (a weekday name is ASCII)
					key := []rune(strings.ToLower(ds))
					if len(key) > 3 {
						key = key[:3]
					}
					if w, found := weekdayNames[string(key)]; found {
						n = float64(w)
					} else {
						n = nil
					}
				}
				w, whole := isWhole(n)
				switch {
				case !whole || w < 0 || w > 6:
					r.add(label + ": " + jsJSON(d) + ` is not a day of the week. Use 0 (Sunday) to 6 (Saturday), or "mon" to "sun".`)
				case contains(days, int(w)):
					r.add(label + " lists the same weekday twice.")
				default:
					days = append(days, int(w))
				}
			}
		}
		price, priceWhole := isWhole(m["priceInr"])
		if !priceWhole || price < 1 || price > 100_000 {
			r.add(label + ` needs the price of one month in whole rupees ("priceInr"), for example 2400.`)
		} else if price > dailyRefundInr {
			r.add(label + " costs " + language.FormatInr(price) + " a month, which is more than the " + language.FormatInr(dailyRefundInr) +
				" that can be refunded in a day: a customer who cancels could not be paid back. Lower the price.")
		}
		if idOK && slotOK && len(days) > 0 && priceWhole && len(names) == len(s.Languages) {
			sort.Ints(days) // `days.sort()` sorts as text; the days are 0 to 6, one digit each, so it is the same order
			types = append(types, PlanType{ID: id, Names: names, SlotID: slotID, Weekdays: days, PriceInr: int64(price)})
		}
	}
	if !planCutOK || len(types) == 0 || !creditsOK {
		return nil
	}
	return &PlansSettings{Types: types, Cutoff: cutoff, Credits: credits.(string)}
}

// ---- helpers other files use ----------------------------------------------------------------------------------------------------------------------------------------------

// ItemName is settings.ts itemName: the name the agent says for an item in a language, falling back to English, Hindi, Malayalam, Kannada and then the id.
func ItemName(item *MenuItem, lang string) string {
	for _, l := range []string{lang, "en", "hi", "ml", "kn"} {
		if n := item.Names[l]; len(n) > 0 {
			return n[0]
		}
	}
	return item.ID
}

// ItemOf is settings.ts itemOf: the menu item with this id, or nil.
func (s *Settings) ItemOf(id string) *MenuItem {
	for i := range s.Menu {
		if s.Menu[i].ID == id {
			return &s.Menu[i]
		}
	}
	return nil
}

// AllSlots is settings.ts allSlots: every slot, pickup first, each with its way.
func (s *Settings) AllSlots() []SlotOfMode {
	var out []SlotOfMode
	for i := range s.Pickup {
		out = append(out, SlotOfMode{&s.Pickup[i], Pickup})
	}
	if s.Delivery != nil {
		for i := range s.Delivery.Slots {
			out = append(out, SlotOfMode{&s.Delivery.Slots[i], Delivery})
		}
	}
	return out
}

// SlotOf is settings.ts slotOf: the slot with this id and its way; ok false when there is none.
func (s *Settings) SlotOf(id string) (SlotOfMode, bool) {
	for _, x := range s.AllSlots() {
		if x.Slot.ID == id {
			return x, true
		}
	}
	return SlotOfMode{}, false
}

// SlotsOf is the slots of one way (pickup.slots, or delivery?.slots ?? []).
func (s *Settings) SlotsOf(mode string) []Slot {
	if mode == Pickup {
		return s.Pickup
	}
	if s.Delivery != nil {
		return s.Delivery.Slots
	}
	return nil
}

// CutoffOf is settings.ts cutoffOf: the slot's own cut-off, or the shop's.
func (s *Settings) CutoffOf(sl *Slot) Cutoff {
	if sl.Cutoff != nil {
		return *sl.Cutoff
	}
	return s.Cutoff
}

// highestOrderOnly is the most items, all of the dearest item (the part of highestOrderInr validateSettings checks before the plans are read).
func (s *Settings) highestOrderOnly() int64 {
	var dearest int64
	for i, it := range s.Menu {
		if i == 0 || it.PriceInr > dearest {
			dearest = it.PriceInr
		}
	}
	return s.Orders.MaxItemsPerOrder * dearest
}

// HighestOrderInr is settings.ts highestOrderInr: the dearest one payment can be, in rupees: the most items of the dearest item, or a plan's month if that is dearer. It bounds a
// payment link and a refund, so Guard can hold the same number.
func (s *Settings) HighestOrderInr() int64 { return max(s.highestOrderOnly(), s.HighestPlanInr()) }

// HighestPlanInr is plans/settings.ts highestPlanInr: the dearest plan's month (0 for none).
func (s *Settings) HighestPlanInr() int64 {
	var n int64
	if s.Plans != nil {
		for _, t := range s.Plans.Types {
			n = max(n, t.PriceInr)
		}
	}
	return n
}

// AdvanceFor is settings.ts advanceFor: the advance for an order total in whole rupees: all of it, or the percentage rounded up (never 0, never more than the total). Integer
// arithmetic: Math.ceil(total * percent / 100) of whole numbers is the ceiling of the integer quotient.
func (s *Settings) AdvanceFor(totalInr int64) int64 {
	if s.Advance.Mode == "full" {
		return totalInr
	}
	p := totalInr * s.Advance.Percent
	ceil := p / 100
	if p%100 > 0 {
		ceil++
	}
	return min(totalInr, max(1, ceil))
}

// LowestLinkInr is settings.ts LOWEST_LINK_INR: the least any one payment link can be for, in rupees (generated, settings_check.json).
func LowestLinkInr() int64 { return checkWords.LowestLinkInr }

// PlanTypeOf is plans/settings.ts planTypeOf: the plan type with this id, or nil.
func (s *Settings) PlanTypeOf(id string) *PlanType {
	if s.Plans == nil {
		return nil
	}
	for i := range s.Plans.Types {
		if s.Plans.Types[i].ID == id {
			return &s.Plans.Types[i]
		}
	}
	return nil
}

// PlanName is plans/settings.ts planName: the plan's name in a language, else English, else the first language that has one (the shop's languages' order, as the names were
// read), else the id.
func PlanName(t *PlanType, lang string) string {
	if n := t.Names[lang]; len(n) > 0 {
		return n[0]
	}
	if n := t.Names["en"]; len(n) > 0 {
		return n[0]
	}
	// Object.values(type.names)[0]: the names object is built in the shop's languages' order; a Go map has none, so LANGUAGES' order is tried (a plan has a name in every one
	// of the shop's languages, so the first two tries always find one in a checked file)
	for _, l := range runtime.LANGUAGES {
		if n := t.Names[l]; len(n) > 0 {
			return n[0]
		}
	}
	return t.ID
}

// OwnerMarked: the owner marks the money (a UPI shop, whose module cannot confirm a payment by itself).
func (s *Settings) OwnerMarked() bool { return !s.Capabilities().ConfirmsAutomatically }

// Capabilities is providers/index.ts capabilitiesOf(settings.payment): what the shop's payment module can do (UPI: the owner marks and refunds by hand; Razorpay: it confirms and
// refunds by itself), from the providers' own declarations (generated, settings_check.json). An unknown module is the default's.
func (s *Settings) Capabilities() payments.Capabilities {
	c, ok := checkWords.Capabilities[s.Payment.Module]
	if !ok {
		c = checkWords.Capabilities[checkWords.DefaultModule]
	}
	return payments.Capabilities{ConfirmsAutomatically: c.ConfirmsAutomatically, RefundsAutomatically: c.RefundsAutomatically, TakesPartPayments: c.TakesPartPayments,
		Cancels: c.Cancels, ReadsBack: c.ReadsBack, ReadsSettlements: c.ReadsSettlements}
}

// UpiPayLink is ownerMarkedOf(settings.payment).payLink: the `upi://pay` link with the shop's own UPI ID and payee, the exact amount and the reference as its note. nil for a shop
// that is not owner-marked.
func (s *Settings) UpiPayLink() ownermarked.PayLink {
	if s.Payment.Module != "upi" {
		return nil
	}
	return func(amountPaise int64, note string) (string, error) {
		return upi.PayLink(upi.Request{Vpa: s.Payment.UpiID, Payee: s.Payment.Payee, AmountPaise: amountPaise, Note: note})
	}
}

// WordsShop is the small part of the settings internal/orders/words reads (its Shop's comment says which field is which).
func (s *Settings) WordsShop() *words.Shop {
	ws := &words.Shop{Name: s.Name, Timezone: s.Timezone, AdvancePercent: s.Advance.Percent, CutoffTime: s.Cutoff.Time, WindowHours: s.Cancellation.WindowHours}
	for _, it := range s.Menu {
		ws.Menu = append(ws.Menu, words.MenuItem{ID: it.ID, Names: it.Names, PriceInr: it.PriceInr})
	}
	if len(s.Pickup) > 0 {
		ws.PickupFrom, ws.PickupTo = s.Pickup[0].From, s.Pickup[0].To
	}
	if s.Delivery != nil && len(s.Delivery.Area) > 0 {
		ws.DeliveryArea = s.Delivery.Area[0]
	}
	return ws
}
